#include <iostream>
using namespace std;
int main() {
    int n, s = 0;
    cin >> n;
    if (n == 0) {
        cout << 0;
        return 0;
    }
    while (n > 0) {
        s += n % 10;
        n /= 10;
    }
    cout << s;
    return 0;
}

