#include <iostream>
using namespace std;
int main() {
    long long n;
    cin >> n;
    if (n < 2) {
        cout << "NU";
        return 0;
    }
    for (long long d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            cout << "NU";
            return 0;
        }
    }
    cout << "DA";
    return 0;
}
